  const parsePrimary = () => {
    skipWhitespace();

    const c = peek();

    // Unary +
    if (c === '+') {
      consume();
      const val = parsePrimary();
      return val;
    }

    // Unary -
    if (c === '-') {
      consume();
      const val = parsePrimary();
      return -val;
    }

    // Parenthesized expression
    if (c === '(') {
      consume();
      skipWhitespace();
