    throw new SyntaxError('SyntaxError: Empty expression');
  }

  const result = parseAdditive();

  skipWhitespace();

  if (peek() != null) {
    throw new SyntaxError('SyntaxError: Unexpected characters after expression');
  }

  return result;
}
