from math import inf

def shortest_distances(n, edges, source):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")
    if not isinstance(source, int) or source < 0 or source >= n:
        raise ValueError("source must be a valid node (0 <= source < n)")

    if not isinstance(edges, list):
        raise ValueError("edges must be a list")

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if not isinstance(u, int) or u < 0 or u >= n:
            raise ValueError("edge start node must be a valid node")
        if not isinstance(v, int) or v < 0 or v >= n:
            raise ValueError("edge end node must be a valid node")
        if not isinstance(w, (int, float)) or w < 0:
            raise ValueError("edge weight must be a non-negative number")
        adj[u].append((v, w))

    dist = [inf] * n
    dist[source] = 0
    pq = [(0, source)]

    while pq:
        d, u = heappop(pq)

        if d > dist[u]:
            continue

        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heappush(pq, (dist[v], v))

    return dist
