def convert_base(number, from_base, to_base):
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36.")

    if not number or number.strip() == "":
        raise ValueError("Input string is empty.")

    if number.startswith("-"):
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    if not number:
        raise ValueError("Input string is empty.")

    digits_map = {str(i): i for i in range(10)}
    digits_map.update({chr(ord('a') + i): 10 + i for i in range(26)})
    digits_map.update({chr(ord('A') + i): 10 + i for i in range(26)})

    value_map = {v: k for k, v in digits_map.items()}

    try:
        digits = []
        for char in number:
            if char not in digits_map:
                raise ValueError(f"Invalid digit '{char}' for base {from_base}.")
            d = digits_map[char]
            if d >= from_base:
                raise ValueError(f"Invalid digit '{char}' for base {from_base}.")
            digits.append(d)

        # Handle zero explicitly (e.g., "0", "00")
        if not digits:
            return "0"

        result_digits = []
        temp = 0

        # Convert from from_base to decimal (base 10)
        for d in reversed(digits):
            temp = temp * from_base + d

    except ValueError:
        raise

    if temp == 0:
        return "0"

    # Convert from decimal to to_base
    while temp > 0:
        remainder = temp % to_base
        temp = temp // to_base
        result_digits.append(value_map[remainder])

    result_digits.reverse()
    result = ''.join(result_digits)

    if is_negative:
        result = "-" + result

    return result
