export function parseQuery(query) {
    if (typeof query !== 'string') {
        return {};
    }

    const result = {};

    // Remove leading '?' if present
    const cleanQuery = query.startsWith('?') ? query.slice(1) : query;

    // Split by '&'
    const pairs = cleanQuery.split('&');

    for (const pair of pairs) {
        if (pair.length === 0) {
            continue;
        }

        const eqIndex = pair.indexOf('=');
        let key;
        let value;

        if (eqIndex === -1) {
            key = pair;
            value = '';
        } else {
            key = pair.slice(0, eqIndex);
            value = pair.slice(eqIndex + 1);
        }

        // Decode + to space
        let decodedKey = key.replace(/\+/g, ' ');
        let decodedValue = value.replace(/\+/g, ' ');

        // Percent decode
        try {
            decodedKey = decodeURIComponent(decodedKey);
            decodedValue = decodeURIComponent(decodedValue);
        } catch (e) {
            // Keep as is, but keep the converted spaces
        }

        const keys = result[key];
        if (keys === undefined) {
            result[key] = decodedValue;
        } else {
            if (Array.isArray(keys)) {
                keys.push(decodedValue);
            } else {
                result[key] = [keys, decodedValue];
            }
        }
    }

    // Ensure keys that could be prototype properties are own properties
    // by iterating over result and setting them explicitly on a plain object
    // that won't inherit prototype pollution in a way that affects the global context.
    // We create a new object and copy properties to ensure safety.
    const safeResult = {};
    for (const key of Object.keys(result)) {
        safeResult[key] = result[key];
    }

    return safeResult;
}
