export function deepEqual(a, b) {
  // SameValueZero comparison for primitives (NaN === NaN, 0 === -0)
  const sameValueZero = (x, y) => x === y || (x !== x && y !== y);

  // Helper to check if a value is a plain object
  const isPlainObject = (o) => o !== null && typeof o === 'object' && !Array.isArray(o) && !(o instanceof Date);

  // Helper to check if a value is a Date
  const isDate = (o) => o instanceof Date;

  // Helper to get the time value of a Date
  const getTime = (o) => o.getTime();

  // Helper to get the keys of an object (own enumerable string keys)
  const getKeys = (o) => Object.keys(o);

  // Helper to check if two objects have the same keys
  const hasSameKeys = (keys1, keys2) => {
    if (keys1.length !== keys2.length) return false;
    for (let i = 0; i < keys1.length; i++) {
      if (keys1[i] !== keys2[i]) return false;
    }
    return true;
  };

  // Helper to check if two objects have equal values for each key
  const hasEqualValues = (obj1, obj2, keys) => {
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      const val1 = obj1[key];
      const val2 = obj2[key];
      if (!sameValueZero(val1, val2)) return false;
      if (val1 !== null && val2 !== null) {
        if (!deepEqual(val1, val2)) return false;
      }
    }
    return true;
  };

  // Helper to handle cyclic structures using a map to track visited objects
  const cycleCheck = (a, b, visited) => {
    if (!visited.has(a)) {
      visited.set(a, new Set());
    }
    if (!visited.has(b)) {
      visited.set(b, new Set());
    }

    const aVisited = visited.get(a);
    const bVisited = visited.get(b);

    if (aVisited.has(b)) {
      return true; // Same cycle
    }

    if (bVisited.has(a)) {
      return false; // Different cycles
    }

    aVisited.add(b);
    bVisited.add(a);

    if (typeof a !== typeof b ||
        (typeof a === 'object' && typeof b === 'object') &&
        (a === null || b === null ||
         Array.isArray(a) !== Array.isArray(b) ||
         (isPlainObject(a) && isPlainObject(b) && !hasSameKeys(getKeys(a), getKeys(b))) ||
         (isDate(a) && isDate(b) && !sameValueZero(getTime(a), getTime(b)))) {
      return false;
    }

    return deepEqual(a, b, visited);
  };

  // Main logic
  return cycleCheck(a, b, new Map());
}
