            }
            result = a / b;
            break;
          default:
            throw new SyntaxError('Unknown operator');
        }

        stack.push(result);
      }
    }

    if (stack.length !== 1) {
      throw new SyntaxError('Invalid expression structure');
    }

    return stack[0];
  }

  return evaluateRPN(rpn);
